import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import path from 'node:path';
import {loadEnv,preflight} from '../lib/env.mjs';
import {createSession} from '../lib/harness.mjs';
const env=await loadEnv();assert.ok(['localhost','127.0.0.1'].includes(new URL(env.baseUrl).hostname));await preflight(env);
const output=path.resolve('qa/2026-10-01_comprehensive-audit_ui35-short-field-final');await fs.mkdir(output,{recursive:true});
const ctx=await createSession({env,role:'ADMIN',evidenceDir:output,runId:'UI35-SHORT'});
const proof={role:ctx.role,account:ctx.username,states:[],writes:[]};
const save=async()=>fs.writeFile(path.join(output,'driver-assertions.json'),JSON.stringify({...proof,errors:ctx.errors},null,2)+'\n');
async function reads(){const detail=await ctx.apiGet('/quotations/45'),versions=await ctx.apiGet('/quotations/45/versions');assert.equal(detail.status,200);assert.equal(versions.status,200);return{detail,versions};}
async function capture(width,label){const shot=await ctx.screenshot(`${width}-${label}`);const dom=await ctx.page.evaluate(()=>{const e=document.querySelector('[aria-label="Hệ số Hải Phòng-NEWEB 1.25T"]');const style=getComputedStyle(e);const canvas=document.createElement('canvas');const c=canvas.getContext('2d');c.font=style.font;return{url:location.pathname,text:document.body.innerText,value:e.value,rect:e.getBoundingClientRect().toJSON(),focused:document.activeElement===e,font:style.font,textWidth:c.measureText(e.value).width,padding:Number.parseFloat(style.paddingLeft)+Number.parseFloat(style.paddingRight),outline:style.outline,outlineOffset:style.outlineOffset,documentWidth:document.documentElement.scrollWidth,width:innerWidth};});const domPath=shot.replace(/\.png$/,'-dom.json');await fs.writeFile(domPath,JSON.stringify(dom,null,2)+'\n');proof.states.push({width,label,shot,domPath,dom});await save();assert.equal(dom.rect.width,72);assert.equal(dom.rect.height,30);assert.ok(dom.textWidth<=dom.rect.width-dom.padding-2,'Complete short number visible');assert.ok(dom.documentWidth<=width);return dom;}
async function clear(input){await input.click();const n=await input.evaluate(e=>e.value.length);for(let i=0;i<n;i++)await ctx.page.keyboard.press('ArrowRight');for(let i=0;i<n;i++)await ctx.page.keyboard.press('Backspace');assert.equal(await input.evaluate(e=>e.value),'');}
try{await ctx.page.setRequestInterception(true);ctx.page.on('request',r=>{if(['POST','PUT','PATCH','DELETE'].includes(r.method())){proof.writes.push({method:r.method(),url:r.url()});void r.abort('blockedbyclient');}else void r.continue();});const before=await reads();proof.before=before;assert.equal(before.versions.body.items[0].version,3);for(const width of[390,768,1440]){await ctx.page.setViewport({width,height:900,hasTouch:width<900});await ctx.goto('/config/quotations');const h=await ctx.page.evaluateHandle(name=>[...document.querySelectorAll('.quotation-frames tbody tr')].find(e=>e.textContent.includes(name)),before.detail.body.templateName);assert.ok(h.asElement());await h.asElement().click();await ctx.page.waitForSelector('.quotation-route-block input');await ctx.settle(350);const input=await ctx.page.$('[aria-label="Hệ số Hải Phòng-NEWEB 1.25T"]');assert.ok(input);await input.click();await capture(width,'original-focused');await clear(input);await capture(width,'blank-draft');await ctx.page.keyboard.press('Tab');await ctx.settle(300);const restored=await capture(width,'blank-restored-no-write');assert.equal(restored.value,'1');assert.equal(proof.writes.length,0);for(const value of['100','1.25']){await clear(input);await ctx.page.keyboard.type(value);const dom=await capture(width,`${value==='100'?'three-digit':'decimal'}-focused-draft`);assert.equal(dom.value,value);assert.ok(dom.focused);}await clear(input);await ctx.page.keyboard.type('1');await ctx.page.keyboard.press('Tab');await ctx.settle(300);await capture(width,'original-draft-restored-before-blur');assert.equal(proof.writes.length,0);assert.deepEqual(await reads(),before);}proof.after=await reads();assert.deepEqual(proof.after,before);assert.equal(ctx.errors.length,0);proof.complete=true;await save();console.log(JSON.stringify({complete:true,states:proof.states.length,widths:[390,768,1440],blankAttempts:0,writes:0,threeDigitsAndDecimalVisible:true,version:3}));}finally{await save();await ctx.browser.close();}
